//! Characterization replay against the frozen upstream oracle.
//!
//! The fixtures under `tests/data/` are generated by driving the REAL
//! `@opentui/core@0.5.14` (bun, sandbox-pinned) through:
//!
//! * `tools/diff/js/char-corpus.ts` — the parser surface: 6392 key
//!   sequences (legacy + kitty profiles), 163 mouse cases (single /
//!   run / stateful), and 12 paste decodes;
//! * `tools/diff/js/event-corpus.ts` — the renderer event pipeline:
//!   372 feeds through a real `createTestRenderer` stdin with the
//!   keypress/keyrelease/paste event log captured from
//!   `renderer.keyInput` (the InternalKeyHandler), one fresh renderer
//!   per case (the StdinParser is stateful).
//!
//! The Rust side replays every case and must match EXACTLY —
//! field-by-field for parsed keys (including the `undefined`-vs-`false`
//! distinction upstream's optional fields carry) and event-for-event
//! for the renderer feed.

use opentui_core::events::{KeyEvent, KeyHandlerEvent, PasteEvent};
use opentui_core::parse_keypress::{
    parse_keypress, KeyEventType, KeySource, ParseKeypressOptions, ParsedKey,
};
use opentui_core::parse_mouse::MouseParser;
use opentui_core::parse_mouse::{MouseEventType, ScrollDirection};
use opentui_core::paste::decode_paste_bytes;
use opentui_core::{create_cli_renderer, CliRendererConfig};
use serde::Deserialize;
use std::sync::{Arc, Mutex};

// ---------------------------------------------------------------------------
// fixture shapes
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct Corpus {
    keys: Vec<KeyCase>,
    mouse: Vec<MouseCase>,
    paste: Vec<PasteCase>,
}

#[derive(Deserialize)]
struct KeyCase {
    input: Vec<u32>,
    legacy: Option<ExpectedKey>,
    kitty: Option<ExpectedKey>,
}

#[derive(Deserialize, Debug, Clone)]
struct ExpectedKey {
    name: String,
    ctrl: bool,
    meta: bool,
    shift: bool,
    option: bool,
    sequence: Vec<u32>,
    number: bool,
    raw: Vec<u32>,
    #[serde(rename = "eventType")]
    event_type: String,
    source: String,
    code: Option<String>,
    #[serde(rename = "super")]
    super_key: Option<bool>,
    hyper: Option<bool>,
    #[serde(rename = "capsLock")]
    caps_lock: Option<bool>,
    #[serde(rename = "numLock")]
    num_lock: Option<bool>,
    #[serde(rename = "baseCode")]
    base_code: Option<u32>,
    repeated: Option<bool>,
}

#[derive(Deserialize)]
struct MouseCase {
    input: serde_json::Value,
    #[serde(default)]
    single: Option<ExpectedMouse>,
    #[serde(default)]
    all: Option<Vec<ExpectedMouse>>,
    #[serde(default)]
    stateful: Option<Vec<ExpectedMouse>>,
}

#[derive(Deserialize, Debug, Clone)]
struct ExpectedMouse {
    #[serde(rename = "type")]
    event_type: String,
    button: i32,
    x: i32,
    y: i32,
    modifiers: ExpectedModifiers,
    scroll: Option<ExpectedScroll>,
}

#[derive(Deserialize, Debug, Clone)]
struct ExpectedModifiers {
    shift: bool,
    alt: bool,
    ctrl: bool,
}

#[derive(Deserialize, Debug, Clone)]
struct ExpectedScroll {
    direction: String,
    delta: u32,
}

#[derive(Deserialize)]
struct PasteCase {
    input: Vec<u32>,
    text: Vec<u32>,
}

#[derive(Deserialize)]
struct EventCorpus {
    legacy: Vec<EventCase>,
    kitty: Vec<EventCase>,
}

#[derive(Deserialize)]
struct EventCase {
    label: String,
    #[serde(default)]
    chunks: Vec<Vec<u32>>,
    #[serde(default)]
    events: Vec<serde_json::Value>,
}

// ---------------------------------------------------------------------------
// comparison
// ---------------------------------------------------------------------------

fn cps(bytes: &[u32]) -> String {
    bytes.iter().filter_map(|c| char::from_u32(*c)).collect()
}

fn cmp_key(label: &str, actual: &ParsedKey, expected: &ExpectedKey) {
    let where_mismatch = |field: &str, a: String, e: String| {
        panic!("corpus mismatch [{label}] {field}: rust {a:?} vs oracle {e:?}");
    };
    if actual.name != expected.name {
        where_mismatch("name", actual.name.clone(), expected.name.clone());
    }
    if actual.ctrl != expected.ctrl {
        where_mismatch("ctrl", actual.ctrl.to_string(), expected.ctrl.to_string());
    }
    if actual.meta != expected.meta {
        where_mismatch("meta", actual.meta.to_string(), expected.meta.to_string());
    }
    if actual.shift != expected.shift {
        where_mismatch(
            "shift",
            actual.shift.to_string(),
            expected.shift.to_string(),
        );
    }
    if actual.option != expected.option {
        where_mismatch(
            "option",
            actual.option.to_string(),
            expected.option.to_string(),
        );
    }
    if actual.number != expected.number {
        where_mismatch(
            "number",
            actual.number.to_string(),
            expected.number.to_string(),
        );
    }
    let actual_seq: Vec<u32> = actual.sequence.chars().map(u32::from).collect();
    if actual_seq != expected.sequence {
        where_mismatch(
            "sequence",
            format!("{actual_seq:?}"),
            format!("{:?}", expected.sequence),
        );
    }
    let actual_raw: Vec<u32> = actual.raw.chars().map(u32::from).collect();
    if actual_raw != expected.raw {
        where_mismatch(
            "raw",
            format!("{actual_raw:?}"),
            format!("{:?}", expected.raw),
        );
    }
    let et = match actual.event_type {
        KeyEventType::Press => "press",
        KeyEventType::Repeat => "repeat",
        KeyEventType::Release => "release",
    };
    if et != expected.event_type {
        where_mismatch("eventType", et.into(), expected.event_type.clone());
    }
    let src = match actual.source {
        KeySource::Raw => "raw",
        KeySource::Kitty => "kitty",
    };
    if src != expected.source {
        where_mismatch("source", src.into(), expected.source.clone());
    }
    if actual.code != expected.code {
        where_mismatch(
            "code",
            format!("{:?}", actual.code),
            format!("{:?}", expected.code),
        );
    }
    if actual.super_key != expected.super_key {
        where_mismatch(
            "super",
            format!("{:?}", actual.super_key),
            format!("{:?}", expected.super_key),
        );
    }
    if actual.hyper != expected.hyper {
        where_mismatch(
            "hyper",
            format!("{:?}", actual.hyper),
            format!("{:?}", expected.hyper),
        );
    }
    if actual.caps_lock != expected.caps_lock {
        where_mismatch(
            "capsLock",
            format!("{:?}", actual.caps_lock),
            format!("{:?}", expected.caps_lock),
        );
    }
    if actual.num_lock != expected.num_lock {
        where_mismatch(
            "numLock",
            format!("{:?}", actual.num_lock),
            format!("{:?}", expected.num_lock),
        );
    }
    if actual.base_code != expected.base_code {
        where_mismatch(
            "baseCode",
            format!("{:?}", actual.base_code),
            format!("{:?}", expected.base_code),
        );
    }
    if actual.repeated != expected.repeated {
        where_mismatch(
            "repeated",
            format!("{:?}", actual.repeated),
            format!("{:?}", expected.repeated),
        );
    }
}

fn load_corpus() -> Corpus {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/char-corpus.json");
    let data = std::fs::read(path).expect("char-corpus.json fixture");
    serde_json::from_slice(&data).expect("corpus JSON")
}

fn load_event_corpus() -> EventCorpus {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/event-corpus.json");
    let data = std::fs::read(path).expect("event-corpus.json fixture");
    serde_json::from_slice(&data).expect("event corpus JSON")
}

// ---------------------------------------------------------------------------
// parser corpus
// ---------------------------------------------------------------------------

#[test]
fn keypress_corpus_legacy() {
    let corpus = load_corpus();
    let mut checked = 0usize;
    let mut nulls = 0usize;
    for case in &corpus.keys {
        let input = cps(&case.input);
        let actual = parse_keypress(&input, ParseKeypressOptions::default());
        match (&case.legacy, &actual) {
            (Some(expected), Some(parsed)) => {
                let label = format!("legacy {:?}", case.input);
                cmp_key(&label, parsed, expected);
                checked += 1;
            }
            (None, None) => nulls += 1,
            (expected, actual) => panic!(
                "legacy presence mismatch {:?}: oracle {:?}, rust is {}",
                case.input,
                expected.is_some(),
                actual.is_some()
            ),
        }
    }
    assert!(checked > 6000, "corpus coverage {checked}");
    assert!(nulls > 0);
}

#[test]
fn keypress_corpus_kitty() {
    let corpus = load_corpus();
    let mut checked = 0usize;
    for case in &corpus.keys {
        let input = cps(&case.input);
        let actual = parse_keypress(
            &input,
            ParseKeypressOptions {
                use_kitty_keyboard: true,
            },
        );
        match (&case.kitty, &actual) {
            (Some(expected), Some(parsed)) => {
                let label = format!("kitty {:?}", case.input);
                cmp_key(&label, parsed, expected);
                checked += 1;
            }
            (None, None) => {}
            (expected, actual) => panic!(
                "kitty presence mismatch {:?}: oracle {:?}, rust is {}",
                case.input,
                expected.is_some(),
                actual.is_some()
            ),
        }
    }
    assert!(checked > 6000, "corpus coverage {checked}");
}

#[test]
fn mouse_corpus() {
    let corpus = load_corpus();
    let mut checked = 0usize;
    for case in &corpus.mouse {
        // input is either a byte array (single sequence) or an array of
        // byte arrays (the stateful case)
        let seqs: Vec<Vec<u8>> = match &case.input {
            serde_json::Value::Array(items)
                if items.first().is_some_and(|i| i.as_u64().is_some()) =>
            {
                vec![items.iter().map(|b| b.as_u64().unwrap() as u8).collect()]
            }
            serde_json::Value::Array(items) => items
                .iter()
                .map(|seq| {
                    seq.as_array()
                        .unwrap()
                        .iter()
                        .map(|b| b.as_u64().unwrap() as u8)
                        .collect()
                })
                .collect(),
            other => panic!("unexpected mouse input shape {other:?}"),
        };

        if let Some(expected) = &case.single {
            let mut parser = MouseParser::new();
            let actual = parser.parse_mouse_event(&seqs[0]);
            let actual = actual.as_ref().expect("oracle expects an event");
            cmp_mouse(&format!("single {:?}", seqs[0]), actual, expected);
            checked += 1;
        }
        if let Some(expected) = &case.all {
            let mut parser = MouseParser::new();
            let actual = parser.parse_all_mouse_events(&seqs[0]);
            assert_eq!(actual.len(), expected.len(), "run length {:?}", seqs[0]);
            for (a, e) in actual.iter().zip(expected) {
                cmp_mouse(&format!("all {:?}", seqs[0]), a, e);
            }
            checked += 1;
        }
        if let Some(expected) = &case.stateful {
            let mut parser = MouseParser::new();
            for (seq, e) in seqs.iter().zip(expected) {
                let a = parser
                    .parse_mouse_event(seq)
                    .unwrap_or_else(|| panic!("stateful {:?} missing event", seq));
                cmp_mouse(&format!("stateful {seq:?}"), &a, e);
            }
            checked += 1;
        }
    }
    assert!(checked > 300);
}

fn cmp_mouse(
    label: &str,
    actual: &opentui_core::parse_mouse::RawMouseEvent,
    expected: &ExpectedMouse,
) {
    let type_str = actual.event_type.as_str();
    assert_eq!(type_str, expected.event_type, "{label} type");
    assert_eq!(actual.button, expected.button, "{label} button");
    assert_eq!(actual.x, expected.x, "{label} x");
    assert_eq!(actual.y, expected.y, "{label} y");
    assert_eq!(
        actual.modifiers.shift, expected.modifiers.shift,
        "{label} shift"
    );
    assert_eq!(actual.modifiers.alt, expected.modifiers.alt, "{label} alt");
    assert_eq!(
        actual.modifiers.ctrl, expected.modifiers.ctrl,
        "{label} ctrl"
    );
    match (&actual.scroll, &expected.scroll) {
        (None, None) => {}
        (Some(a), Some(e)) => {
            assert_eq!(
                a.direction.as_str(),
                e.direction.as_str(),
                "{label} scroll direction"
            );
            assert_eq!(a.delta, e.delta, "{label} scroll delta");
        }
        (a, e) => panic!("{label} scroll presence: rust {a:?} vs oracle {e:?}"),
    }
}

#[test]
fn paste_decode_corpus() {
    let corpus = load_corpus();
    for case in &corpus.paste {
        let bytes: Vec<u8> = case.input.iter().map(|b| *b as u8).collect();
        let actual = decode_paste_bytes(&bytes);
        let expected: String = case
            .text
            .iter()
            .filter_map(|c| char::from_u32(*c))
            .collect();
        assert_eq!(actual, expected, "paste bytes {:?}", case.input);
    }
}

// ---------------------------------------------------------------------------
// renderer event corpus (oracle event mode)
// ---------------------------------------------------------------------------

/// The Rust event log shape recorded from [`opentui_core::CliRenderer`].
#[derive(Debug, Clone)]
enum RecordedEvent {
    Key { release: bool, key: ParsedKey },
    Paste { bytes: Vec<u8> },
}

fn record_feed(kitty: bool, chunks: &[Vec<u32>]) -> Vec<RecordedEvent> {
    let mut renderer = create_cli_renderer(CliRendererConfig {
        width: 40,
        height: 10,
        kitty_keyboard: if kitty {
            Some(opentui_core::renderer::KittyKeyboardOptions::default())
        } else {
            None
        },
        ..Default::default()
    });
    let events: Arc<Mutex<Vec<RecordedEvent>>> = Arc::new(Mutex::new(Vec::new()));

    let key_log = Arc::clone(&events);
    let _press_sub =
        renderer
            .key_input
            .on_key(KeyHandlerEvent::Keypress, move |e: &mut KeyEvent| {
                key_log.lock().unwrap().push(RecordedEvent::Key {
                    release: false,
                    key: e.key.clone(),
                });
            });
    let rel_log = Arc::clone(&events);
    let _release_sub =
        renderer
            .key_input
            .on_key(KeyHandlerEvent::Keyrelease, move |e: &mut KeyEvent| {
                rel_log.lock().unwrap().push(RecordedEvent::Key {
                    release: true,
                    key: e.key.clone(),
                });
            });
    let paste_log = Arc::clone(&events);
    let _paste_sub = renderer.key_input.on_paste(move |e: &mut PasteEvent| {
        paste_log.lock().unwrap().push(RecordedEvent::Paste {
            bytes: e.bytes.clone(),
        });
    });

    for chunk in chunks {
        let bytes: Vec<u8> = chunk.iter().map(|b| *b as u8).collect();
        renderer.feed_bytes(&bytes);
    }
    let recorded = events.lock().unwrap().clone();
    recorded
}

fn cmp_events(label: &str, recorded: &[RecordedEvent], expected: &[serde_json::Value]) {
    assert_eq!(
        recorded.len(),
        expected.len(),
        "{label}: event count rust {} vs oracle {}",
        recorded.len(),
        expected.len()
    );
    for (r, e) in recorded.iter().zip(expected) {
        let kind = e["kind"].as_str().unwrap_or_default();
        match (r, kind) {
            (RecordedEvent::Key { release, key }, "keypress") => {
                assert!(!release, "{label}: expected press, got release");
                let expected: ExpectedKey =
                    serde_json::from_value(e.clone()).expect("expected key event shape");
                cmp_key(label, key, &expected);
            }
            (RecordedEvent::Key { release, key }, "keyrelease") => {
                assert!(release, "{label}: expected release, got press");
                let expected: ExpectedKey =
                    serde_json::from_value(e.clone()).expect("expected key event shape");
                cmp_key(label, key, &expected);
            }
            (RecordedEvent::Paste { bytes }, "paste") => {
                let expected_bytes: Vec<u8> = e["bytes"]
                    .as_array()
                    .map(|a| a.iter().map(|b| b.as_u64().unwrap_or(0) as u8).collect())
                    .unwrap_or_default();
                assert_eq!(bytes, &expected_bytes, "{label}: paste bytes");
            }
            (r, kind) => panic!("{label}: event kind mismatch: rust {r:?} vs oracle {kind}"),
        }
    }
}

fn run_event_profile(cases: &[EventCase], kitty: bool) {
    let mut compared = 0usize;
    let mut empty = 0usize;
    for case in cases {
        let recorded = record_feed(kitty, &case.chunks);
        if case.events.is_empty() && recorded.is_empty() {
            // deferred / filtered class: both sides produce nothing
            empty += 1;
            continue;
        }
        cmp_events(&case.label, &recorded, &case.events);
        compared += 1;
    }
    assert!(compared > 160, "event-mode coverage {compared}");
    let _ = empty;
}

#[test]
fn oracle_event_mode_legacy() {
    let corpus = load_event_corpus();
    run_event_profile(&corpus.legacy, false);
}

#[test]
fn oracle_event_mode_kitty() {
    let corpus = load_event_corpus();
    run_event_profile(&corpus.kitty, true);
}

