fn _scroll_direction_doc(d: ScrollDirection) -> &'static str {
    d.as_str()
}

// MouseEventType import used by cmp_mouse docs
#[allow(dead_code)]
fn _mouse_event_type_doc(t: MouseEventType) -> &'static str {
    t.as_str()
}
